INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('qi-chunqiu','齐','["齐","姜齐","田齐","齐国"]',NULL,'{"periods":[{"rank":"侯","start":{"year":-1046,"month":1,"confidence":"year"},"end":{"year":-335,"month":12,"confidence":"year"}},{"rank":"王","start":{"year":-334,"month":1,"confidence":"year"},"end":{"year":-221,"month":12,"confidence":"month"}}]}','cn','east_asia',-1046,1,NULL,'year',-221,12,NULL,'month',-12540,-2629,'ochre',NULL,NULL,'周武王封姜太公于齐；前386年田氏代齐；前221年秦灭齐。');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jiang-dai','贷','qi-chunqiu','[]','姜','齐',NULL,NULL,NULL,NULL,-379,1,NULL,'year','["君主"]','齐康公（姜贷），姜齐末代。前404年继宣公；前391年田和放逐于海上，姜齐在齐君位止。前379年卒，姜太公之祀绝。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/齐康公"},{"label":"《史记·齐太公世家》","url":"https://zh.wikisource.org/wiki/史記/卷032"},{"label":"《史记·十二诸侯年表》","url":"https://zh.wikisource.org/wiki/史記/卷014"}]','康公',NULL,'齐康公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('jiang-xiaobai','小白','qi-chunqiu','[]','姜','齐',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','齐桓公（小白），僖公之子，前685–前643年在位。任用管仲改革，尊王攘夷，九合诸侯，为春秋五霸之首。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/齐桓公"},{"label":"《史记·齐太公世家》","url":"https://zh.wikisource.org/wiki/史記/卷032"},{"label":"《史记·十二诸侯年表》","url":"https://zh.wikisource.org/wiki/史記/卷014"},{"label":"《春秋左氏传·僖公》","url":"https://zh.wikisource.org/wiki/春秋左氏傳/僖公"},{"label":"春秋鲁国历法复原（据张培瑜《中国古代历法》）","url":"https://ytliu0.github.io/ChineseCalendar/chunqiu_simp.html"}]','桓公',NULL,'齐桓公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('lv-shang','尚','qi-chunqiu','["姜子牙","姜太公","太公"]','姜','吕',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主","军事家","政治家"]','姜姓，吕氏，名尚，号太公望，通称姜子牙。辅佐周文王、武王，参与克商，前1046年受封于齐营丘；因当地风俗修政，发展工商与鱼盐之利。卒年有异说，一说约前1026年卒，其子吕伋继为齐丁公。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/姜子牙"},{"label":"《史记·齐太公世家》","url":"https://zh.wikisource.org/wiki/史記/卷032"},{"label":"维基百科：齐国君主列表（早期年代与正文表有异）","url":"https://zh.wikipedia.org/wiki/齐国君主列表#姜齊君主列表"},{"label":"《资治通鉴外纪》成王条（太公卒年异说）","url":"https://www.shidianguji.com/book/SBCK033/chapter/SBCK033_14"},{"label":"维基百科：齐国君主表（早期推定年代）","url":"https://zh.wikipedia.org/wiki/齐国#姜齊君主列表"}]','太公',NULL,'齐太公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qi-r1','伋','qi-chunqiu','[]','姜','齐',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','齐太公之子，名伋，史书称吕伋。继太公为齐君，约前1026年至前975年间在位。《尚书·顾命》记其以齐侯身份参与迎立周康王，《左传》记其与熊绎、伯禽等共事康王。卒后其子得继位为乙公。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/齐丁公"},{"label":"《史记·齐太公世家》","url":"https://zh.wikisource.org/wiki/史記/卷032"},{"label":"《尚书·顾命》","url":"https://zh.wikisource.org/wiki/尚書/顧命"},{"label":"维基百科：齐国君主列表（早期年代与正文表有异）","url":"https://zh.wikipedia.org/wiki/齐国君主列表#姜齊君主列表"},{"label":"维基百科：齐国君主表（早期推定年代）","url":"https://zh.wikipedia.org/wiki/齐国#姜齊君主列表"}]','丁公',NULL,'齐丁公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qi-r10','脱','qi-chunqiu','[]','姜','齐',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','齐文公之子，名脱，一作说。前803—前795年在位。《史记》记其继父位，九年卒，子购继位为庄公；《十二诸侯年表》所列年次与此相符。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/齐成公"},{"label":"《史记·齐太公世家》","url":"https://zh.wikisource.org/wiki/史記/卷032"},{"label":"《史记·十二诸侯年表》","url":"https://zh.wikisource.org/wiki/史記/卷014"}]','成公',NULL,'齐成公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qi-r11','购','qi-chunqiu','[]','姜','齐',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','齐成公之子，名购，为区别后来的齐庄公光，通称齐前庄公。前794—前731年在位，共六十四年；二十四年周幽王被犬戎杀害，周室东迁。卒后由子禄甫继位为釐公。','[{"label":"维基百科：齐庄公（购）","url":"https://zh.wikipedia.org/wiki/齊莊公_(購)"},{"label":"《史记·齐太公世家》","url":"https://zh.wikisource.org/wiki/史記/卷032"},{"label":"《史记·十二诸侯年表》","url":"https://zh.wikisource.org/wiki/史記/卷014"}]','庄公',NULL,'齐庄公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qi-r12','禄甫','qi-chunqiu','[]','姜','齐',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','齐釐公（禄甫），庄公之子，前730–前698年在位。伐纪、伐鲁，齐国国势渐强，为襄公霸业奠基。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/齐釐公"},{"label":"《史记·齐太公世家》","url":"https://zh.wikisource.org/wiki/史記/卷032"},{"label":"《史记·十二诸侯年表》","url":"https://zh.wikisource.org/wiki/史記/卷014"}]','釐公',NULL,'齐釐公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qi-r13','诸儿','qi-chunqiu','[]','姜','齐',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','齐襄公（诸儿），僖公之子，前697–前686年在位。与文姜乱伦，荒于政事，终为连称、管至父弑杀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/齐襄公"},{"label":"《史记·齐太公世家》","url":"https://zh.wikisource.org/wiki/史記/卷032"},{"label":"《史记·十二诸侯年表》","url":"https://zh.wikisource.org/wiki/史記/卷014"},{"label":"《春秋左氏传·庄公》","url":"https://zh.wikisource.org/wiki/春秋左氏傳/莊公"},{"label":"春秋鲁国历法复原（据张培瑜《中国古代历法》）","url":"https://ytliu0.github.io/ChineseCalendar/chunqiu_simp.html"}]','襄公',NULL,'齐襄公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qi-r14','无知','qi-chunqiu','[]','姜','齐',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','公孙无知，齐庄公之孙、釐公之弟夷仲年之子。前686年襄公被弑后获立，次年前685年春为雍廪所杀；齐国一度无君，公子小白随后入齐即位为桓公。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/公孙无知"},{"label":"《史记·齐太公世家》","url":"https://zh.wikisource.org/wiki/史記/卷032"},{"label":"《史记·十二诸侯年表》","url":"https://zh.wikisource.org/wiki/史記/卷014"},{"label":"《春秋左氏传·庄公》","url":"https://zh.wikisource.org/wiki/春秋左氏傳/莊公"},{"label":"春秋鲁国历法复原（据张培瑜《中国古代历法》）","url":"https://ytliu0.github.io/ChineseCalendar/chunqiu_simp.html"}]',NULL,NULL,'公孙无知','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qi-r16','无诡','qi-chunqiu','[]','姜','齐',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','公子无亏，又称无诡，齐桓公之子。前643年桓公卒后由易牙、竖刁拥立，孝公昭奔宋；前642年春为齐人所杀，随后宋襄公助昭返国即位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/公子无亏"},{"label":"《史记·齐太公世家》","url":"https://zh.wikisource.org/wiki/史記/卷032"},{"label":"《史记·十二诸侯年表》","url":"https://zh.wikisource.org/wiki/史記/卷014"},{"label":"《春秋左氏传·僖公》","url":"https://zh.wikisource.org/wiki/春秋左氏傳/僖公"},{"label":"春秋鲁国历法复原（据张培瑜《中国古代历法》）","url":"https://ytliu0.github.io/ChineseCalendar/chunqiu_simp.html"}]',NULL,NULL,'公子无亏','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qi-r17','昭','qi-chunqiu','[]','姜','齐',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','齐孝公（昭），桓公之子，郑姬所生，前642–前633年在位。宋襄公会诸侯护送回国即位，霸业已衰。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/齐孝公"},{"label":"《史记·齐太公世家》","url":"https://zh.wikisource.org/wiki/史記/卷032"},{"label":"《史记·十二诸侯年表》","url":"https://zh.wikisource.org/wiki/史記/卷014"},{"label":"《春秋左氏传·僖公》","url":"https://zh.wikisource.org/wiki/春秋左氏傳/僖公"},{"label":"春秋鲁国历法复原（据张培瑜《中国古代历法》）","url":"https://ytliu0.github.io/ChineseCalendar/chunqiu_simp.html"}]','孝公',NULL,'齐孝公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qi-r18','潘','qi-chunqiu','[]','姜','齐',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','齐昭公（潘），桓公之子，葛嬴所生，前632–前613年在位。杀孝公之子夺位，曾随晋文公城濮伐楚。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/齐昭公"},{"label":"《史记·齐太公世家》","url":"https://zh.wikisource.org/wiki/史記/卷032"},{"label":"《史记·十二诸侯年表》","url":"https://zh.wikisource.org/wiki/史記/卷014"},{"label":"《春秋左氏传·文公》","url":"https://zh.wikisource.org/wiki/春秋左氏傳/文公"}]','昭公',NULL,'齐昭公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qi-r19','舍','qi-chunqiu','[]','姜','齐',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','齐君舍，齐昭公与子叔姬之子。前613年父卒后即位，当年为其叔父公子商人所杀，商人自立为齐懿公。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/舍_(齊國)"},{"label":"《史记·齐太公世家》","url":"https://zh.wikisource.org/wiki/史記/卷032"},{"label":"《史记·十二诸侯年表》","url":"https://zh.wikisource.org/wiki/史記/卷014"},{"label":"《春秋左氏传·文公》","url":"https://zh.wikisource.org/wiki/春秋左氏傳/文公"}]',NULL,NULL,'君舍','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qi-r2','得','qi-chunqiu','[]','姜','齐',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','齐丁公之子，名得，又称叔乙。继丁公为齐君，约前975年至前933年间在位，卒后由子慈母继位。《通志·氏族略》载丁公嫡子季子让国于叔乙，季子食采于崔，为崔氏始祖。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/齐乙公"},{"label":"《史记·齐太公世家》","url":"https://zh.wikisource.org/wiki/史記/卷032"},{"label":"维基百科：齐国君主列表（早期年代与正文表有异）","url":"https://zh.wikipedia.org/wiki/齐国君主列表#姜齊君主列表"},{"label":"维基百科：齐国君主表（早期推定年代）","url":"https://zh.wikipedia.org/wiki/齐国#姜齊君主列表"}]','乙公',NULL,'齐乙公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qi-r20','商人','qi-chunqiu','[]','姜','齐',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','齐懿公（商人），桓公之子，前612–前609年在位。骄横好杀，因夺邴氏田邑之怨，为邴歜刺杀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/齐懿公"},{"label":"《史记·齐太公世家》","url":"https://zh.wikisource.org/wiki/史記/卷032"},{"label":"《史记·十二诸侯年表》","url":"https://zh.wikisource.org/wiki/史記/卷014"},{"label":"《春秋左氏传·文公》","url":"https://zh.wikisource.org/wiki/春秋左氏傳/文公"}]','懿公',NULL,'齐懿公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qi-r21','元','qi-chunqiu','[]','姜','齐',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','齐惠公（元），桓公之子，少卫姬所生，前608–前599年在位。曾避国内乱出奔卫国，后回国即位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/齐惠公"},{"label":"《史记·齐太公世家》","url":"https://zh.wikisource.org/wiki/史記/卷032"},{"label":"《史记·十二诸侯年表》","url":"https://zh.wikisource.org/wiki/史記/卷014"}]','惠公',NULL,'齐惠公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qi-r22','无野','qi-chunqiu','[]','姜','齐',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','齐顷公（无野），惠公之子，前598–前582年在位。戏晋使引发鞍之战，后又与晋议和修好。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/齐顷公"},{"label":"《史记·齐太公世家》","url":"https://zh.wikisource.org/wiki/史記/卷032"},{"label":"《史记·十二诸侯年表》","url":"https://zh.wikisource.org/wiki/史記/卷014"}]','顷公',NULL,'齐顷公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qi-r23','环','qi-chunqiu','[]','姜','齐',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','齐灵公，名环，顷公之子，前581—前554年在位。晏婴父子相继辅政，晚年欲废太子光而立公子牙；病重时崔杼迎回光，灵公卒后光继位为庄公。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/齐灵公"},{"label":"《史记·齐太公世家》","url":"https://zh.wikisource.org/wiki/史記/卷032"},{"label":"《史记·十二诸侯年表》","url":"https://zh.wikisource.org/wiki/史記/卷014"}]','灵公',NULL,'齐灵公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qi-r24','光','qi-chunqiu','[]','姜','齐',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','齐庄公，名光，灵公之子，前553—前548年在位。支持栾盈返晋争权，又与崔杼之妻私通，后为崔杼所弑，景公继位，齐国卿族争权加剧。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/齊莊公_(光)"},{"label":"《史记·齐太公世家》","url":"https://zh.wikisource.org/wiki/史記/卷032"},{"label":"《史记·十二诸侯年表》","url":"https://zh.wikisource.org/wiki/史記/卷014"}]','庄公',NULL,'齐庄公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qi-r25','杵臼','qi-chunqiu','[]','姜','齐',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','齐景公，名杵臼，庄公异母弟，前547—前490年在位。晏婴曾辅政；晚年立幼子荼为嗣，卒后国惠子、高昭子奉荼继位，随后发生田乞拥立阳生的政变。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/齐景公"},{"label":"《史记·齐太公世家》","url":"https://zh.wikisource.org/wiki/史記/卷032"},{"label":"《史记·十二诸侯年表》","url":"https://zh.wikisource.org/wiki/史記/卷014"},{"label":"《春秋左氏传·哀公》","url":"https://zh.wikisource.org/wiki/春秋左氏傳/哀公"}]','景公',NULL,'齐景公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qi-r26','荼','qi-chunqiu','[]','姜','齐',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','安孺子，名荼，齐景公幼子。前490年景公卒后由国惠子、高昭子奉立，前489年田乞政变后被废杀，阳生继位为悼公。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/安孺子"},{"label":"《史记·齐太公世家》","url":"https://zh.wikisource.org/wiki/史記/卷032"},{"label":"《史记·十二诸侯年表》","url":"https://zh.wikisource.org/wiki/史記/卷014"},{"label":"《春秋左氏传·哀公》","url":"https://zh.wikisource.org/wiki/春秋左氏傳/哀公"}]',NULL,NULL,'安孺子','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qi-r27','阳生','qi-chunqiu','[]','姜','齐',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','齐悼公（阳生），景公之子，前488–前485年在位。田乞所立，杀芮子诛大夫，后被弑，田氏专权日甚。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/齐悼公"},{"label":"《史记·齐太公世家》","url":"https://zh.wikisource.org/wiki/史記/卷032"},{"label":"《史记·十二诸侯年表》","url":"https://zh.wikisource.org/wiki/史記/卷014"},{"label":"《春秋左氏传·哀公》","url":"https://zh.wikisource.org/wiki/春秋左氏傳/哀公"}]','悼公',NULL,'齐悼公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qi-r28','壬','qi-chunqiu','[]','姜','齐',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','齐简公（壬），悼公之子，前484–前481年在位。任用田常与阚止为相，阚止被杀，简公亦遇害。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/齐简公"},{"label":"《史记·齐太公世家》","url":"https://zh.wikisource.org/wiki/史記/卷032"},{"label":"《史记·十二诸侯年表》","url":"https://zh.wikisource.org/wiki/史記/卷014"}]','简公',NULL,'齐简公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qi-r29','骜','qi-chunqiu','[]','姜','齐',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','齐平公（骜），简公之弟，前480–前456年在位。田成子杀简公而立之，田氏为太宰，君主沦为傀儡。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/齐平公"},{"label":"《史记·齐太公世家》","url":"https://zh.wikisource.org/wiki/史記/卷032"},{"label":"《史记·十二诸侯年表》","url":"https://zh.wikisource.org/wiki/史記/卷014"}]','平公',NULL,'齐平公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qi-r3','慈母','qi-chunqiu','[]','姜','齐',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','齐乙公之子，名慈母。继乙公为齐君，约前933年至前902年间在位，卒后由子不辰继位为哀公。哀公、胡公静与献公山为其后嗣。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/齐癸公"},{"label":"《史记·齐太公世家》","url":"https://zh.wikisource.org/wiki/史記/卷032"},{"label":"维基百科：齐国君主列表（早期年代与正文表有异）","url":"https://zh.wikipedia.org/wiki/齐国君主列表#姜齊君主列表"},{"label":"维基百科：齐国君主表（早期推定年代）","url":"https://zh.wikipedia.org/wiki/齐国#姜齊君主列表"}]','癸公',NULL,'齐癸公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qi-r30','积','qi-chunqiu','[]','姜','齐',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','齐宣公（积），平公之子，前455–前405年在位。田氏把持国政，前453年韩赵魏灭智氏，春秋步入尾声。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/齐宣公"},{"label":"《史记·齐太公世家》","url":"https://zh.wikisource.org/wiki/史記/卷032"},{"label":"《史记·十二诸侯年表》","url":"https://zh.wikisource.org/wiki/史記/卷014"}]','宣公',NULL,'齐宣公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qi-r33','剡','qi-chunqiu','[]','妫','田',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','田侯剡，田和之子，田齐第二代君主，前383—前375年在位。后被其弟田午所杀，田午继位为桓公。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/田侯剡"},{"label":"《史记·田敬仲完世家》","url":"https://zh.wikisource.org/wiki/史記/卷046"},{"label":"维基百科：齐国君主列表（年表及异说）","url":"https://zh.wikipedia.org/wiki/齐国君主列表"}]',NULL,NULL,'剡','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qi-r34','午','qi-chunqiu','[]','妫','田',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','田齐桓公，名午，田和之子、田侯剡之弟。杀剡夺位，前374—前357年为在位年表所列年次；卒后其子因齐继位为威王。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/田午"},{"label":"《史记·田敬仲完世家》","url":"https://zh.wikisource.org/wiki/史記/卷046"},{"label":"维基百科：齐国君主列表（年表及异说）","url":"https://zh.wikipedia.org/wiki/齐国君主列表"}]','桓公',NULL,'齐桓公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qi-r35','因齐','qi-chunqiu','[]','妫','田',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','齐威王（因齐），桓公之子，前356–前320年在位。任用邹忌、田忌，悬赏纳谏，齐国大治称强。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/齐威王"},{"label":"《史记·田敬仲完世家》","url":"https://zh.wikisource.org/wiki/史記/卷046"},{"label":"维基百科：齐国君主列表（年表及异说）","url":"https://zh.wikipedia.org/wiki/齐国君主列表"}]','威王',NULL,'齐威王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qi-r36','辟彊','qi-chunqiu','[]','妫','田',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','齐宣王（辟彊），威王之子，前319–前301年在位。招贤延士，稷下学宫兴盛，促成合纵攻秦。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/齐宣王"},{"label":"《史记·田敬仲完世家》","url":"https://zh.wikisource.org/wiki/史記/卷046"},{"label":"维基百科：齐国君主列表（年表及异说）","url":"https://zh.wikipedia.org/wiki/齐国君主列表"}]','宣王',NULL,'齐宣王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qi-r37','地','qi-chunqiu','[]','妫','田',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','齐湣王（地），宣王之子，前300–前284年在位。灭宋扩土，后为燕将乐毅联合五国攻破临淄，逃亡被杀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/齐湣王"},{"label":"《史记·田敬仲完世家》","url":"https://zh.wikisource.org/wiki/史記/卷046"},{"label":"维基百科：齐国君主列表（年表及异说）","url":"https://zh.wikipedia.org/wiki/齐国君主列表"}]','湣王',NULL,'齐湣王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qi-r38','法章','qi-chunqiu','[]','妫','田',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','齐襄王（法章），湣王庶子匿民间，前283–前265年在位。田单收复临淄，齐国复国但国力大衰。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/齐襄王"},{"label":"《史记·田敬仲完世家》","url":"https://zh.wikisource.org/wiki/史記/卷046"},{"label":"维基百科：齐国君主列表（年表及异说）","url":"https://zh.wikipedia.org/wiki/齐国君主列表"}]','襄王',NULL,'齐襄王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qi-r39','建','qi-chunqiu','[]','妫','田',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','齐王建（建），襄王之子，前264–前221年在位。战国末代齐君，不修战备，秦将王贲攻齐，投降而亡国。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/齊王建"},{"label":"《史记·田敬仲完世家》","url":"https://zh.wikisource.org/wiki/史記/卷046"},{"label":"维基百科：齐国君主列表（年表及异说）","url":"https://zh.wikipedia.org/wiki/齐国君主列表"}]',NULL,NULL,'建','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qi-r4','不辰','qi-chunqiu','[]','姜','齐',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','齐癸公之子，名不辰，一作不臣。继父为齐君；据《史记·齐太公世家》，纪侯向周王进谗，周王烹杀哀公，另立其异母弟静为胡公。献公山为其同母弟。《竹书纪年》将烹杀记于周夷王三年，绝对年代有异说。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/齐哀公"},{"label":"《史记·齐太公世家》","url":"https://zh.wikisource.org/wiki/史記/卷032"},{"label":"《太平御览》卷八十五引《竹书纪年》","url":"https://zh.wikisource.org/wiki/太平御覽/0085"},{"label":"夏商周断代工程与其他西周年代方案对照","url":"https://zh.wikipedia.org/wiki/夏商周断代工程#年表"},{"label":"维基百科：齐国君主列表（早期年代与正文表有异）","url":"https://zh.wikipedia.org/wiki/齐国君主列表#姜齊君主列表"},{"label":"维基百科：齐国君主表（早期推定年代）","url":"https://zh.wikipedia.org/wiki/齐国#姜齊君主列表"}]','哀公',NULL,'齐哀公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qi-r5','静','qi-chunqiu','[]','姜','齐',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','齐哀公异母弟，名静。哀公被周王烹杀后获立为齐君，迁都薄姑。哀公同母弟公子山与其党率营丘人袭杀胡公，自立为献公；胡公之子随后被驱逐。即位年份有异说，不能据此断言仅在位二年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/齐胡公"},{"label":"《史记·齐太公世家》","url":"https://zh.wikisource.org/wiki/史記/卷032"},{"label":"《太平御览》卷八十五引《竹书纪年》","url":"https://zh.wikisource.org/wiki/太平御覽/0085"},{"label":"夏商周断代工程与其他西周年代方案对照","url":"https://zh.wikipedia.org/wiki/夏商周断代工程#年表"},{"label":"维基百科：齐国君主列表（早期年代与正文表有异）","url":"https://zh.wikipedia.org/wiki/齐国君主列表#姜齊君主列表"},{"label":"维基百科：齐国君主表（早期推定年代）","url":"https://zh.wikipedia.org/wiki/齐国#姜齊君主列表"}]','胡公',NULL,'齐胡公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qi-r6','山','qi-chunqiu','[]','姜','齐',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','齐哀公同母弟、胡公异母弟，名山。率营丘人袭杀胡公后自立，逐胡公之子，迁都临淄。《史记》记其九年卒，子寿继位；按武公共和年次回溯，年表在位为前859—前851年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/齐献公"},{"label":"《史记·齐太公世家》","url":"https://zh.wikisource.org/wiki/史記/卷032"},{"label":"《史记·十二诸侯年表》","url":"https://zh.wikisource.org/wiki/史記/卷014"}]','献公',NULL,'齐献公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qi-r7','寿','qi-chunqiu','[]','姜','齐',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','齐献公之子，名寿。前850—前825年在位。《史记》记其九年周厉王奔彘，十年王室共和；《十二诸侯年表》以共和元年为武公十年。二十六年卒，子无忌继位为厉公。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/齐武公"},{"label":"《史记·齐太公世家》","url":"https://zh.wikisource.org/wiki/史記/卷032"},{"label":"《史记·十二诸侯年表》","url":"https://zh.wikisource.org/wiki/史記/卷014"}]','武公',NULL,'齐武公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qi-r8','无忌','qi-chunqiu','[]','姜','齐',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','齐武公之子，名无忌。前824—前816年在位。因暴虐，齐人欲立胡公之子，联合攻杀厉公；胡公之子亦战死。齐人随后立厉公之子赤为文公，并诛杀参与弑君者七十人。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/齐厉公"},{"label":"《史记·齐太公世家》","url":"https://zh.wikisource.org/wiki/史記/卷032"},{"label":"《史记·十二诸侯年表》","url":"https://zh.wikisource.org/wiki/史記/卷014"}]','厉公',NULL,'齐厉公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('qi-r9','赤','qi-chunqiu','[]','姜','齐',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','齐厉公之子，名赤。厉公被杀后获立，前815—前804年在位；即位时齐人诛杀参与杀厉公者七十人。《史记》记其十二年卒，子脱继位为成公。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/齐文公"},{"label":"《史记·齐太公世家》","url":"https://zh.wikisource.org/wiki/史記/卷032"},{"label":"《史记·十二诸侯年表》","url":"https://zh.wikisource.org/wiki/史記/卷014"}]','文公',NULL,'齐文公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('sun-bin','孙膑','qi-chunqiu','[]',NULL,NULL,-378,1,NULL,'year',-316,1,NULL,'year','["军事家"]','战国齐国军事家，曾遭庞涓陷害而受膑刑，后在齐国任军师。协助田忌于桂陵、马陵击败魏军；《史记》称其为孙武后裔，但世系缺乏独立证据，具体身世仍有争议。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/孙膑"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('tian-he','和','qi-chunqiu','[]','妫','田',NULL,NULL,NULL,NULL,-384,1,NULL,'year','["君主"]','田庄子之子。田氏自陈完入齐后长期经营宗族，田乞、田常相继控制齐廷，田常于前481年杀齐简公后更专国政。田和继掌家族势力，前391年迁齐康公于海上，取得实际统治；前386年经魏文侯向周室请命，列为诸侯，田氏正式代齐。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/田和"},{"label":"《史记·田敬仲完世家》","url":"https://zh.wikisource.org/wiki/史記/卷046"},{"label":"维基百科：齐国君主列表（年表及异说）","url":"https://zh.wikipedia.org/wiki/齐国君主列表"}]','太公',NULL,'齐太公','[]');
